def occurance_substring(string, substring):
    # Initialize an empty list to store the positions
    positions = []

    # Loop through the string to find all occurrences of the substring
    for i in range(len(string)):
        # Check if the current character matches the first character of the substring
        if string[i] == substring[0]:
            # Start checking from the next character
            j = i + 1
            # Continue checking until the entire substring is found or we reach the end of the string
            while j < len(string) and string[j:j+len(substring)] == substring:
                # If the substring is found, add its starting index to the positions list
                positions.append(j)
                # Move to the next character after the matched substring
                j += len(substring)

    # If no occurrences are found, return None
    if not positions:
        return None

    # Return the positions as a tuple
    return (substring, min(positions), max(positions))

